package de.crew;
import de.crew.client.*;import java.util.concurrent.atomic.AtomicLong;import java.nio.file.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import io.netty.buffer.Unpooled;import net.minecraft.network.RegistryFriendlyByteBuf;import java.util.*;
public class FeaturesTest{public static void main(String[] args)throws Exception{
var now=new AtomicLong();var clicks=new ClickCounter(now::get);clicks.click();now.set(999999999);if(clicks.count()!=1)throw new AssertionError();now.set(1000000000);if(clicks.count()!=0)throw new AssertionError();for(int i=0;i<600;i++)clicks.click();if(clicks.count()!=500)throw new AssertionError();
var f=Files.createTempFile("crew-test",".png");try{var img=new BufferedImage(128,64,BufferedImage.TYPE_INT_ARGB);img.setRGB(0,0,0xff123456);ImageIO.write(img,"png",f.toFile());byte[] pixels=CapeImage.read(f);if(pixels.length!=8192||java.nio.ByteBuffer.wrap(pixels).getInt()!=0xff123456)throw new AssertionError();var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),null);try{var p=new CapePayload(UUID.randomUUID(),pixels);CapePayload.CODEC.encode(b,p);var r=CapePayload.CODEC.decode(b);if(!r.valid()||!r.player().equals(p.player())||!Arrays.equals(r.pixels(),pixels))throw new AssertionError();}finally{b.release();}Files.writeString(f,"not png");try{CapeImage.read(f);throw new AssertionError();}catch(java.io.IOException expected){} }finally{Files.deleteIfExists(f);}
if(new CapePayload(UUID.randomUUID(),new byte[4]).valid())throw new AssertionError();System.out.println("PASS: CPS expiry/cap, PNG normalization/rejection, personal cape protocol");}}
